fn check_lamp_arrangement(r: i8, g: i8, b: i8) -> bool {
    // To avoid any potential overflow when summing or doubling,
    // cast to a wider integer type.
    let r = r as i16;
    let g = g as i16;
    let b = b as i16;

    let total = r + g + b;
    let max_count = r.max(g).max(b);

    // Feasibility condition: 2 * max_count <= total + 1
    2 * max_count <= total + 1
}

